package demo1;

public class Demotow {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		char num = '-';
		int a = 10, b = 20;

		switch (num) {
		case '+':
			System.out.println("a+b");
			break;
		case '-':
			System.out.println("a-b");
			break;
		case '*':
			System.out.println('*');
			break;
		case '%':
			System.out.println("a%b");
			break;
		}
	}
}
